import { test, expect } from '@playwright/test';
import fs, { readFileSync } from 'fs';
import { execSync } from 'child_process';

test(
  'mock users generated by python',
  async ({ page }) => {


    const filePath =
      'data/mocks/generated-users.json';

    if (!fs.existsSync(filePath)) {

      execSync(
        'python tools/generate_mock_users.py',
        {
          stdio: 'inherit'
        }
      );

    }

    const generatedUsers =
      JSON.parse(
        readFileSync(
          filePath,
          'utf8'
        )
      );


    await page.route(
      'https://reqres.in/api/users*',
      async route => {

        await route.fulfill({

          status: 200,

          contentType:
            'application/json',

          body: JSON.stringify(
            generatedUsers
          )

        });

      }
    );

    const response =
      await page.evaluate(
        async () => {

          const response =
            await fetch(
              'https://reqres.in/api/users?page=2'
            );

          return await response.json();

        }
      );

    expect(
      response.data.length
    ).toBe(5);

    expect(
      response.data[0].email
    ).toBe(
      'user1@example.com'
    );

  }
);